using System.Net.Http.Json;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using Pedidos.Api.Data;using Pedidos.Api.Models;
namespace Pedidos.Api.Controllers;
[ApiController,Route("api/[controller]")]public sealed class PedidosController(PedidosDbContext db,IHttpClientFactory clients,IConfiguration cfg):ControllerBase
{
 public sealed record DetalleEntrada(int IdProducto,int IdBodega,int Cantidad);public sealed record PedidoEntrada(string Cliente,List<DetalleEntrada> Detalles);private sealed record ProductoDto(int IdProducto,string Nombre,decimal Precio,int IdCategoria,int IdMarca);
 [HttpGet]public async Task<ActionResult<IEnumerable<Pedido>>> Get(CancellationToken ct)=>Ok(await db.Pedidos.AsNoTracking().Include(x=>x.Cliente).Include(x=>x.Detalles).OrderByDescending(x=>x.IdPedido).ToListAsync(ct));
 [HttpGet("{id:int}")]public async Task<ActionResult<Pedido>> Get(int id,CancellationToken ct){var p=await db.Pedidos.AsNoTracking().Include(x=>x.Cliente).Include(x=>x.Detalles).FirstOrDefaultAsync(x=>x.IdPedido==id,ct);return p is null?NotFound():Ok(p);}
 [HttpPost]public async Task<IActionResult> Post(PedidoEntrada input,CancellationToken ct){if(string.IsNullOrWhiteSpace(input.Cliente)||input.Detalles is not{Count:>0}||input.Detalles.Any(x=>x.Cantidad<=0||x.IdBodega<=0||x.IdProducto<=0))return BadRequest(new{mensaje="Cliente y al menos un detalle válido son obligatorios."});var client=clients.CreateClient();var cat=(cfg["Servicios:CatalogoUrl"]??"http://localhost:5069").TrimEnd('/');var inv=(cfg["Servicios:InventarioUrl"]??"http://localhost:5149").TrimEnd('/');var details=new List<DetallePedido>();foreach(var d in input.Detalles){using var r=await client.GetAsync($"{cat}/api/Productos/{d.IdProducto}",ct);if(!r.IsSuccessStatusCode)return BadRequest(new{mensaje=$"Producto {d.IdProducto} no existe en Catálogo."});var product=await r.Content.ReadFromJsonAsync<ProductoDto>(cancellationToken:ct);if(product is null)return BadRequest(new{mensaje="Catálogo devolvió una respuesta inválida."});details.Add(new(){IdProducto=d.IdProducto,IdBodega=d.IdBodega,Cantidad=d.Cantidad,PrecioUnitario=product.Precio});}foreach(var d in details){using var r=await client.PostAsJsonAsync($"{inv}/api/Reservas",new{d.IdProducto,d.IdBodega,d.Cantidad},ct);if(!r.IsSuccessStatusCode)return Conflict(new{mensaje="Inventario no pudo reservar el producto; pedido no creado.",detalle=await r.Content.ReadAsStringAsync(ct)});}var cliente=new Cliente{Nombre=input.Cliente.Trim()};var pedido=new Pedido{Cliente=cliente,Fecha=DateTime.UtcNow,Estado="Confirmado",Detalles=details};db.Pedidos.Add(pedido);await db.SaveChangesAsync(ct);return CreatedAtAction(nameof(Get),new{id=pedido.IdPedido},pedido);}
}
